struct Node {uint64_t address{},parent{};uint8_t raw[NodeBytes]{};uint32_t payloadOffset{},payloadCaptured{},errors{},reserved{};};
static_assert(sizeof(Node)==280);
struct Item {uint64_t address,parent;};
constexpr unsigned ObjectLimit=16384;
struct Object {uint64_t address{},entity{},vtable{},entityFlags{};uint8_t raw[0xb0]{};uint32_t errors{},reserved{};};
// Append only private capture data. The original proxy/owner prefix is unchanged.
struct GroupData {uint64_t address{},vtable{};uint8_t raw[0x100]{};uint32_t errors{},reserved{};};
static_assert(sizeof(GroupData)==280);
struct GroupObject {Object object;GroupData group;};
static_assert(sizeof(GroupObject)==496);
std::vector<Object> objectInputs[2];
bool objectTruncated[2]{};
// Keep SEH confined to a leaf with no C++ objects/unwinding. Check every region
// and bound all reads; a native allocation can still change between checks.
bool Copy(void* target,uint64_t address,size_t bytes) noexcept {
 if(!bytes)return true;
 if(address<0x10000 || address>0x00007ffffffeffffULL || bytes>4*1024*1024 || address+bytes<address)return false;
 auto at=address;auto end=address+bytes;
 while(at<end){MEMORY_BASIC_INFORMATION m{};
  if(!VirtualQuery(reinterpret_cast<void*>(at),&m,sizeof(m)) || m.State!=MEM_COMMIT || (m.Protect&(PAGE_GUARD|PAGE_NOACCESS)))return false;
  auto regionEnd=reinterpret_cast<uint64_t>(m.BaseAddress)+m.RegionSize;if(regionEnd<=at)return false;
  at=(std::min)(regionEnd,end);
 }
 __try{memcpy(target,reinterpret_cast<void*>(address),bytes);return true;}
 __except(EXCEPTION_EXECUTE_HANDLER){return false;}
}
template<class T>T Get(const void* data,size_t offset){T value{};memcpy(&value,static_cast<const uint8_t*>(data)+offset,sizeof(value));return value;}
bool ReadPtr(uint64_t address,uint64_t& value){return Copy(&value,address,sizeof(value));}
bool Save(const std::filesystem::path& path,const void* data,size_t bytes){
 auto f=_wfsopen(path.c_str(),L"wb",_SH_DENYNO);if(!f)return false;
 bool ok=!bytes || fwrite(data,1,bytes,f)==bytes;ok=fclose(f)==0 && ok;return ok;
}
struct Output {uint64_t address{};uint32_t rawCount{},count{};bool complete{},ok{};std::vector<uint64_t> pointers;};
Output ReadOutput(const uint8_t* query,size_t offset){
 Output o;o.address=Get<uint64_t>(query,offset);o.rawCount=Get<uint32_t>(query,offset+8);o.count=o.rawCount&0x1fffffff;
 o.pointers.resize((std::min)(o.count,OutputLimit));o.ok=Copy(o.pointers.data(),o.address,o.pointers.size()*8);
 if(!o.ok)o.pointers.clear();o.complete=o.ok && o.count==o.pointers.size();return o;
}
void OutputJson(FILE* f,const Output& o){fprintf(f,"{\"address\":\"0x%llx\",\"rawCount\":%u,\"count\":%u,\"captured\":%zu,\"ok\":%s,\"complete\":%s}",o.address,o.rawCount,o.count,o.pointers.size(),o.ok?"true":"false",o.complete?"true":"false");}
// The object list is fixed across both F8 phases. All reads are bounded and
// protected; rejected owners never become an entity-state observation.
void ReadObject(Object& o){
 o.entity=o.vtable=o.entityFlags=0;o.errors=0;
 if(!Copy(o.raw,o.address,sizeof(o.raw))){o.errors=1;return;}
 if((Get<uint32_t>(o.raw,0x2c)&15)!=0)return;
 o.entity=Get<uint64_t>(o.raw,0x90);uint64_t backlink{};
 if(!ReadPtr(o.entity,o.vtable)){o.errors|=2;return;}
 o.vtable=NpcCallback63::CanonicalVtable(o.entity,o.vtable);
 if(o.vtable!=reinterpret_cast<uint64_t>(imageBase)+0x3017d60 && o.vtable!=reinterpret_cast<uint64_t>(imageBase)+0x3019300){o.errors|=4;return;}
 if(!ReadPtr(o.entity+0xf8,backlink) || backlink!=o.address || !Copy(&o.entityFlags,o.entity+0x88,8)){o.errors|=8;return;}
}
void ReadGroup(const Object& object,GroupData& group){
 group={};if(object.errors&1)return;
 // +88 is a parent visibility group only on the verified main geometry proxy.
 if((Get<uint32_t>(object.raw,0x2c)&15)!=0)return;
 group.address=Get<uint64_t>(object.raw,0x88);if(!group.address)return;
 if(!ReadPtr(group.address,group.vtable)){group.errors=1;return;}
 auto base=reinterpret_cast<uint64_t>(imageBase);
 if(group.vtable!=base+0x3099e40 && group.vtable!=base+0x3099e68){group.errors=2;return;}
 if(!Copy(group.raw,group.address,sizeof(group.raw))){group.errors=4;return;}
 uint64_t owner{},type{};
 if(!ReadPtr(object.address+0x88,owner) || owner!=group.address || !ReadPtr(group.address,type) || type!=group.vtable || Get<uint64_t>(group.raw,0)!=group.vtable)group.errors=8;
}
void ObjectsSnapshot(unsigned eye,uint64_t view,const wchar_t* phase,const std::vector<uint64_t>* payload=nullptr){
 if(eye>=2)return;
 LARGE_INTEGER beginTick{},endTick{};QueryPerformanceCounter(&beginTick);
 auto& inputs=objectInputs[eye];
 if(payload){inputs.clear();objectTruncated[eye]=false;std::unordered_set<uint64_t> seen;seen.reserve((std::min)(payload->size(),size_t(ObjectLimit)));
  for(auto p:*payload)if(p && seen.insert(p).second){if(inputs.size()==ObjectLimit){objectTruncated[eye]=true;break;}Object o;o.address=p;inputs.push_back(o);}}
 if(inputs.empty())return;
 std::vector<GroupObject> objects;objects.reserve(inputs.size());
 unsigned read{},owners{},groups{},groupErrors{};for(auto& input:inputs){GroupObject entry;auto& o=entry.object;o.address=input.address;ReadObject(o);ReadGroup(o,entry.group);read+=!(o.errors&1);owners+=o.entity && !o.errors;groups+=entry.group.address && !entry.group.errors;groupErrors+=entry.group.errors!=0;objects.push_back(entry);}
 uint64_t state{},backlink{};std::array<uint8_t,QueryBytes> query{};std::array<uint8_t,0x440> camera{};
 bool identity=ReadPtr(view+0x430,state) && ReadPtr(state+0x8208,backlink) && backlink==view;
 bool contextRead=identity && Copy(query.data(),state+0xfd0,query.size()) && Copy(camera.data(),view,camera.size());
 if(contextRead && payload)for(const auto& input:inputs)NpcCallback63::ConsiderProxy(input.address,query.data()+0x40);
 auto base=directory/(L"interval-"+std::to_wstring(sequence));std::error_code ec;std::filesystem::create_directories(base,ec);if(ec)return;
 auto prefix=base/(std::wstring(L"objects-")+(eye?L"right-":L"left-")+phase);
 auto path=[&](const wchar_t* suffix){return std::filesystem::path(prefix.wstring()+suffix);};
 bool files=Save(path(L".bin"),objects.data(),objects.size()*sizeof(GroupObject));
 if(contextRead)files=Save(path(L"-query.bin"),query.data(),query.size()) && Save(path(L"-view.bin"),camera.data(),camera.size()) && files;
 uint32_t actualSource{};const bool sourceRead=sourceView && Copy(&actualSource,reinterpret_cast<uint64_t>(sourceView)+0x294,4);QueryPerformanceCounter(&endTick);
 auto f=_wfsopen(path(L".json").c_str(),L"w",_SH_DENYNO);if(!f)return;
 fprintf(f,"{\"schema\":2,\"tickBegin\":%llu,\"tickEnd\":%llu,\"thread\":%u,\"viewFrame\":%u,\"actualSourceFrame\":%u,\"sourceFrameRead\":%s,\"sequence\":%llu,\"tracking\":%llu,\"sourceFrame\":%u,\"eye\":%u,\"phase\":\"%ls\",\"objectBytes\":%zu,\"objects\":%zu,\"objectsRead\":%u,\"validatedEntityOwners\":%u,\"truncated\":%s,\"contextRead\":%s,\"filesOK\":%s,\"note\":\"Schema2 private496-byte records: original216-byte proxy/owner prefix plus280-byte parent-group data. Group gate is group+30 bit0 before proxy+20 bit0. Group read requires exact two native vtables and stable proxy/group/type links. Non-atomic selection data, not final geometry.\"}\n",static_cast<unsigned long long>(beginTick.QuadPart),static_cast<unsigned long long>(endTick.QuadPart),GetCurrentThreadId(),Get<uint32_t>(camera.data(),0x294),actualSource,sourceRead?"true":"false",sequence,tracking,sourceFrame,eye,phase,sizeof(GroupObject),objects.size(),read,owners,objectTruncated[eye]?"true":"false",contextRead?"true":"false",files?"true":"false");fclose(f);
 fprintf(logFile,"F8 objects45 interval=%llu eye=%u phase=%ls objects=%zu read=%u owners=%u context=%d files=%d groups=%u groupErrors=%u\n",sequence,eye,phase,objects.size(),read,owners,contextRead,files,groups,groupErrors);fflush(logFile);
}
void ExtraSnapshot(const wchar_t* label,uint64_t view,const wchar_t* phase){
 uint64_t state{},backlink{};std::array<uint8_t,0x8800> raw{};
 bool ok=ReadPtr(view+0x430,state) && ReadPtr(state+0x8208,backlink) && backlink==view && Copy(raw.data(),state,raw.size());
 const auto base=directory/(L"interval-"+std::to_wstring(sequence));std::error_code ec;std::filesystem::create_directories(base,ec);if(ec)return;
 auto prefix=base/(std::wstring(L"extra-")+label+L"-"+phase);
 auto path=[&](const wchar_t* suffix){return std::filesystem::path(prefix.wstring()+suffix);};
 bool files=ok && Save(path(L"-state.bin"),raw.data(),raw.size());
 Output a{},b{};if(ok){auto query=raw.data()+0x2cd0;a=ReadOutput(query,0x888);b=ReadOutput(query,0x898);
  files=Save(path(L"-secondary-output0.bin"),a.pointers.data(),a.pointers.size()*8) && files;
  files=Save(path(L"-secondary-output1.bin"),b.pointers.data(),b.pointers.size()*8) && files;}
 auto f=_wfsopen(path(L".json").c_str(),L"w",_SH_DENYNO);if(!f)return;
 fprintf(f,"{\"sequence\":%llu,\"tracking\":%llu,\"sourceFrame\":%u,\"label\":\"%ls\",\"phase\":\"%ls\",\"readOK\":%s,\"filesOK\":%s,\"state\":\"0x%llx\",\"view\":\"0x%llx\",\"secondaryEnabled\":%s,\"generation\":%llu,\"secondaryMatchesPrimary\":%s,\"queryMatchesSecondary\":%s,\"visibilityGeneration\":%u,\"secondaryOutputs\":[",sequence,tracking,sourceFrame,label,phase,ok?"true":"false",files?"true":"false",state,view,secondaryEnabled?"true":"false",secondaryGeneration,ok&&!memcmp(raw.data()+0x180,raw.data()+0xc0,0xc0)?"true":"false",ok&&!memcmp(raw.data()+0x2d10,raw.data()+0x180,0xc0)?"true":"false",ok?Get<uint32_t>(raw.data(),0x864c):0);
 OutputJson(f,a);fprintf(f,",");OutputJson(f,b);
 fprintf(f,"],\"note\":\"CPU read-only non-atomic snapshot; afterCull secondary query may retain prior execution data. afterEye is after this native eye finishes. Source captured at left cull boundary, not a paired source render.\"}\n");fclose(f);
}
void Snapshot(const wchar_t* label,uint64_t view,uint64_t graph,bool tree){
 uint64_t state{},world{},root{},stateView{},graphView{};
 bool identity=ReadPtr(view+0x430,state) && ReadPtr(graph+8,stateView) && state==stateView && ReadPtr(graph,graphView) && graphView==view && ReadPtr(state+0x8208,stateView) && stateView==view;
 identity=identity && ReadPtr(graph+0x10,world) && ReadPtr(world+0x20,root);
 std::array<uint8_t,QueryBytes> query{},queryAfter{};std::array<uint8_t,0x440> camera{};std::array<uint8_t,0x180> render{};
 uint8_t flag{},separateLists{};bool read=Copy(&separateLists,reinterpret_cast<uint64_t>(imageBase)+0x5fbd814,1) && identity && Copy(camera.data(),view,camera.size()) && Copy(render.data(),state,render.size()) && Copy(query.data(),state+0xfd0,query.size()) && Copy(&flag,state+0x884,1);
 const auto base=directory/(L"interval-"+std::to_wstring(sequence));std::error_code ec;std::filesystem::create_directories(base,ec);if(ec)return;
 auto prefix=base/(std::wstring(L"cull-")+label);auto path=[&](const wchar_t* suffix){return std::filesystem::path(prefix.wstring()+suffix);};
 if(!read){auto f=_wfsopen(path(L".json").c_str(),L"w",_SH_DENYNO);if(f){fprintf(f,"{\"schema\":1,\"sequence\":%llu,\"label\":\"%ls\",\"readOK\":false}\n",sequence,label);fclose(f);}return;}
 auto a=ReadOutput(query.data(),0x888),b=ReadOutput(query.data(),0x898);
 std::vector<Node> nodes;std::vector<uint64_t> payload,payloadCheck;std::vector<Item> pending;std::unordered_set<uint64_t> visited;
 unsigned faults{},duplicates{},unstable{},truncatedPayload{};bool treeComplete=!tree;
 if(tree){nodes.reserve(NodeLimit);payload.reserve(PayloadLimit);payloadCheck.reserve(PerNodeLimit);pending.reserve(NodeLimit);visited.reserve(NodeLimit);pending.push_back({root,0});
  while(!pending.empty() && nodes.size()<NodeLimit){auto item=pending.back();pending.pop_back();
   if(!visited.insert(item.address).second){++duplicates;continue;}
   Node n;n.address=item.address;n.parent=item.parent;n.payloadOffset=static_cast<uint32_t>(payload.size());
   if(!Copy(n.raw,item.address,sizeof(n.raw))){n.errors|=1;++faults;nodes.push_back(n);continue;}
   unsigned count=Get<uint32_t>(n.raw,0x78)&0x1fffffff;
   n.payloadCaptured=(std::min)({count,PerNodeLimit,PayloadLimit-static_cast<unsigned>(payload.size())});
   if(n.payloadCaptured<count){n.errors|=2;++truncatedPayload;}
   auto oldSize=payload.size();payload.resize(oldSize+n.payloadCaptured);
   if(!Copy(n.payloadCaptured?payload.data()+oldSize:nullptr,Get<uint64_t>(n.raw,0x70),n.payloadCaptured*8)){payload.resize(oldSize);n.payloadCaptured=0;n.errors|=4;++faults;}
   payloadCheck.resize(n.payloadCaptured);
   if(n.payloadCaptured && (!Copy(payloadCheck.data(),Get<uint64_t>(n.raw,0x70),n.payloadCaptured*8) || memcmp(payloadCheck.data(),payload.data()+oldSize,n.payloadCaptured*8))){n.errors|=8;++unstable;}
   uint8_t after[NodeBytes]{};
   if(!Copy(after,item.address,sizeof(after)) || memcmp(n.raw+0x70,after+0x70,12) || memcmp(n.raw+0xb0,after+0xb0,0x48)){n.errors|=8;++unstable;}
   for(unsigned i=0;i<4;++i){auto child=Get<uint64_t>(n.raw,0xd8+i*8);if(child){if(pending.size()<NodeLimit)pending.push_back({child,item.address});else{n.errors|=16;++faults;}}}
   nodes.push_back(n);
  }
  treeComplete=pending.empty() && !faults && !duplicates && !unstable && !truncatedPayload;
 }
 bool queryStable=Copy(queryAfter.data(),state+0xfd0,queryAfter.size()) && !memcmp(query.data(),queryAfter.data(),query.size());
 auto aAfter=ReadOutput(query.data(),0x888),bAfter=ReadOutput(query.data(),0x898);
 bool outputsStable=a.ok && b.ok && aAfter.ok && bAfter.ok && a.pointers==aAfter.pointers && b.pointers==bAfter.pointers;
 bool planeMatch=!memcmp(query.data()+0x40,render.data()+0xc0,0xc0);
 bool files=Save(path(L"-query.bin"),query.data(),query.size());
 files=Save(path(L"-view.bin"),camera.data(),camera.size()) && files;
 files=Save(path(L"-state.bin"),render.data(),render.size()) && files;
 files=Save(path(L"-output0.bin"),a.pointers.data(),a.pointers.size()*8) && files;
 files=Save(path(L"-output1.bin"),b.pointers.data(),b.pointers.size()*8) && files;
 if(tree){files=Save(path(L"-nodes.bin"),nodes.data(),nodes.size()*sizeof(Node)) && files;files=Save(path(L"-payload.bin"),payload.data(),payload.size()*8) && files;}
 auto f=_wfsopen(path(L".json").c_str(),L"w",_SH_DENYNO);if(!f)return;
 fprintf(f,"{\"schema\":1,\"sequence\":%llu,\"tracking\":%llu,\"sourceFrameAtBegin\":%u,\"viewFrame\":%u,\"label\":\"%ls\",\"view\":\"0x%llx\",\"graph\":\"0x%llx\",\"state\":\"0x%llx\",\"world\":\"0x%llx\",\"root\":\"0x%llx\",\"readOK\":true,\"filesOK\":%s,\"queryStable\":%s,\"outputsStable\":%s,\"planesMatch\":%s,\"separateListsFlag\":%u,\"state884\":%u,\"query750\":%u,\"nodeBytes\":%zu,\"nodeLimit\":%u,\"nodeCount\":%zu,\"payloadCount\":%zu,\"remainingNodes\":%zu,\"faults\":%u,\"duplicateNodes\":%u,\"unstableNodes\":%u,\"truncatedPayloadNodes\":%u,\"treeComplete\":%s,\"outputs\":[",sequence,tracking,sourceFrame,Get<uint32_t>(camera.data(),0x294),label,view,graph,state,world,root,files?"true":"false",queryStable?"true":"false",outputsStable?"true":"false",planeMatch?"true":"false",separateLists,flag,query[0x750],sizeof(Node),NodeLimit,nodes.size(),payload.size(),pending.size(),faults,duplicates,unstable,truncatedPayload,treeComplete?"true":"false");
 OutputJson(f,a);fprintf(f,",");OutputJson(f,b);
 fprintf(f,"],\"boundary\":\"%s\",\"atomicTreeSnapshot\":false,\"note\":\"CPU reads only; native traversal lock has already been released; output entries are payload object pointers, not node addresses. Inherited classifications are offline replays, not measured native call counts.\"}\n",tree?"after this owned eye nativeCull":"source retained at left-eye boundary; timing not paired");fclose(f);
 if(tree && treeComplete)ObjectsSnapshot(label[0]==L'r'?1:0,view,L"afterCull",&payload);
 fprintf(logFile,"F8 culling interval=%llu label=%ls nodes=%zu payload=%zu output=%u/%u treeComplete=%d queryStable=%d planesMatch=%d faults=%u unstable=%u\n",sequence,label,nodes.size(),payload.size(),a.count,b.count,treeComplete,queryStable,planeMatch,faults,unstable);fflush(logFile);
}
